insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-possible-duplicate-shares-a-word-s698','decision','Possible duplicate: two names of one agency flag a pair only when the rest shares a word','S698 (#3652, COBIx on #3643): the Review card flags two titles naming one agency two ways only when the rest of the titles shares a word (fire and firefighter count as one). Fire CDF Academy still pairs with CAL FIRE Basic Firefighter Training and no longer with CAL FIRE Ethical Leadership in the Classroom. A flag only. His to revise.',array['exhibits','cer','review-card'],'proposed','cpl-project-tracker#3652; tests/exhibits_review_card_panels.test.js',null,null,'SkyAuklet (S698)','2026-11-21'),
('d-term-reports-named-term-s698','decision','A term-report hand-over that names its term clears only that term','S698 (#3652, COBIx on #3646): a term_reports hand-over row that names its term takes only that term off Term Reports Needed; a row naming none counts toward the terms still wanted. commons_handover_summary() carries no term today, so the list still clears on any three hand-overs until it does (commons lane NEXT). His to revise.',array['commons','hand-over','term-reports'],'proposed','cpl-project-tracker#3652; commons_front.js termsWanted',null,null,'SkyAuklet (S698)','2026-11-21'),
('d-dependency-map-hourly-s698','decision','The dependency map is rebuilt once an hour on a timer, never on a push','S698 (#3654, COBIx''s plan on #3476): dependency-map.yml runs at minute 43 of each hour and on dispatch, never on a push; a rebuild per merge wrote 17 map commits of about 1 MB in two days. Sam''s rule of 2026-11-18 stands: one job on main rebuilds the map, a PR never does. The map can trail a merge by an hour. His to revise.',array['repo-size','dependency-map','workflows'],'proposed','cpl-project-tracker#3654; tests/dependency_map_on_main_test.py',null,null,'SkyAuklet (S698)','2026-11-21'),
('p-a11y-sweep-browser-dies-s698','pitfall','The whole a11y sweep lost its browser twice; run a set of targets through a wrapper config','S698: npm run a11y lost its browser partway twice, and every later target read did not finish. A wrapper config that requires a11y.config.js, sets root to the repo and keeps only the wanted targets (--config) ran the 16 Exhibits targets in minutes. The Exhibits Progress target times out on main too (its seed waits for .exh-pg-bar): open.',array['a11y','exhibits','tests'],'proposed','docs/session_700_handoff.md; cpl-project-tracker#3652',null,null,'SkyAuklet (S698)','2026-11-21'),
('m-page-followups-merged-s698','milestone','COBIx''s follow-ups on the Exhibits card and the Commons page merged','S698, 2026-11-21: #3652 (290f5177) merged COBIx''s follow-ups on #3643 and #3646: the Exhibits tab says combine, chips are notes, a failed details read retries on a press, a narrower duplicate flag; the Commons card counts colleges and campuses, the term match, a checked catalog address. #3654 (e470bd7e) put the dependency map on an hourly timer.',array['exhibits','commons','repo-size'],'proposed','cpl-project-tracker#3652; cpl-project-tracker#3654',null,null,'SkyAuklet (S698)','2026-11-21')
on conflict (slug) do nothing;

